<template>
    <div id="map" class="map-container"></div>
    <button v-if="canBack" class="btn-back" @click="goBack">返回全国</button>
</template>

<script setup>
    import { ref, onMounted } from 'vue'
    import Map from 'ol/Map'
    import View from 'ol/View'
    import TileLayer from 'ol/layer/Tile'
    import VectorLayer from 'ol/layer/Vector'
    import VectorSource from 'ol/source/Vector'
    import OSM from 'ol/source/OSM'
    import GeoJSON from 'ol/format/GeoJSON'
    import Select from 'ol/interaction/Select'
    import { pointerMove, click } from 'ol/events/condition'
    import Overlay from 'ol/Overlay'
    import { Style, Stroke, Fill } from 'ol/style'
    import { fromLonLat } from 'ol/proj'

    const canBack = ref(false)
    const currentLayer = ref(null)
    const mapRef = ref(null)

    // 样式定义
    const defaultStyle = () =>
        new Style({
            stroke: new Stroke({ color: '#888', width: 1 }),
            fill: new Fill({ color: 'rgba(0,0,255,0.1)' })
        })
    const hoverStyle = () =>
        new Style({
            stroke: new Stroke({ color: '#f00', width: 2 }),
            fill: new Fill({ color: 'rgba(255,0,0,0.3)' })
        })
    const clickStyle = () =>
        new Style({
            stroke: new Stroke({ color: '#f90', width: 2 }),
            fill: new Fill({ color: 'rgba(255,165,0,0.4)' })
        })

    onMounted(() => {
        const popup = document.createElement('div')
        popup.className = 'ol-popup'
        document.body.appendChild(popup)
        const overlay = new Overlay({
            element: popup,
            positioning: 'bottom-center',
            offset: [0, -10],
            stopEvent: false
        })

        currentLayer.value = createVectorLayer('100000.json', defaultStyle)
        mapRef.value = new Map({
            target: 'map',
            layers: [new TileLayer({ source: new OSM() }), currentLayer.value],
            view: new View({
                center: fromLonLat([104, 35]),
                zoom: 4.5
            }),
            overlays: [overlay]
        })

        const hover = new Select({ condition: pointerMove, style: hoverStyle })
        mapRef.value.addInteraction(hover)

        const clickSelect = new Select({ condition: click, style: clickStyle })
        mapRef.value.addInteraction(clickSelect)

        clickSelect.on('select', (evt) => {
            if (evt.selected.length === 0) return
            const f = evt.selected[0]
            const code = f.get('code') || f.get('properties')?.code
            const name = f.get('name') || f.get('fullname') || '未知'
            const coord = evt.mapBrowserEvent.coordinate
            popup.innerHTML = `📍 ${name}`
            overlay.setPosition(coord)

            if (!canBack.value && (f.get('level') === 1 || f.get('properties')?.level === 1)) {
                drillDownToProvince(code, f)
            }
        })
    })

    function createVectorLayer(filename, styleFn) {
        const source = new VectorSource({
            url: `geojson/${filename}`,
            format: new GeoJSON()
        })
        source.on('error', (e) => {
            console.error(`❌ 加载 geojson/${filename} 失败：`, e)
        })

        return new VectorLayer({
            source,
            style: styleFn
        })
    }

    function drillDownToProvince(code, feature) {
        canBack.value = true
        mapRef.value.getView().fit(feature.getGeometry().getExtent(), { duration: 1000 })
        mapRef.value.removeLayer(currentLayer.value)
        currentLayer.value = createVectorLayer(`${code}.json`, defaultStyle)
        mapRef.value.addLayer(currentLayer.value)
    }

    function goBack() {
        canBack.value = false
        mapRef.value.getView().animate({ zoom: 4.5, center: fromLonLat([104, 35]) })
        mapRef.value.removeLayer(currentLayer.value)
        currentLayer.value = createVectorLayer('100000.json', defaultStyle)
        mapRef.value.addLayer(currentLayer.value)
    }
</script>

<style scoped>
    .map-container {
        width: 100%;
        height: 100vh;
    }

    .ol-popup {
        position: absolute;
        background: #fff;
        padding: 5px 10px;
        border: 1px solid #ccc;
        border-radius: 4px;
        pointer-events: none;
        white-space: nowrap;
    }

    .btn-back {
        position: absolute;
        top: 10px;
        left: 10px;
        z-index: 1000;
        background: white;
        padding: 5px 10px;
        border: 1px solid #888;
        cursor: pointer;
    }
</style>
